import PropTypes from "prop-types";
import React from "react";

import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { compose, bindActionCreators } from "redux";
import { connect } from "react-redux";
import { cx } from "@emotion/css";
import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import Action from "./Action";
import ActionModal from "./ActionModal";
import {
  Button,
  BUTTON_SIZE,
  BUTTON_VARIANT,
  Icon,
} from "@traveloka/soya-components";
import CommonRuleModal from "./CommonRuleModal";
import Condition from "./Condition";
import ConditionModal from "./ConditionModal";
import { ModalManager } from "@traveloka/soya-components";
import { NotificationManager } from "@traveloka/soya-components";
import ToggleTooltip from "./ToggleTooltip/ToggleTooltip";

import * as style from "./CommonRule.styles";

class CommonRuleComponent extends React.Component {
  constructor(props) {
    super(props);
    this.state = { body: this.props.show };
  }

  generateItemAction(actions) {
    const cardActions = [];
    for (let i = 0; i < actions.length; i++) {
      const cardAction = actions[i];
      const actionProps = {};
      let link = null;
      if (cardAction.action) {
        actionProps.onClick = this.runAction.bind(this, cardAction.action);
        link = (
          <a href="#" key={i} {...actionProps} {...cardAction.props}>
            {cardAction.label}
          </a>
        );
      }
      cardActions.push(link);
    }
    return cardActions;
  }

  runAction(action, e) {
    e.preventDefault();
    e.stopPropagation();
    action();
  }

  getRuleConditions() {
    const {
      rule: { conditions },
      index,
    } = this.props;
    const ruleConditions = [];
    for (const i in conditions) {
      ruleConditions.push(
        <Condition
          key={i}
          condition={conditions[i]}
          componentIndex={index}
          index={[Number(i)]}
        />
      );
    }
    return ruleConditions;
  }

  getRuleActions() {
    const {
      rule: { actions },
      index,
    } = this.props;
    const ruleActions = [];
    for (const i in actions) {
      ruleActions.push(
        <Action
          action={actions[i]}
          componentIndex={Number(index)}
          index={Number(i)}
          key={i}
        />
      );
    }
    return ruleActions;
  }

  handleShowHideBody = () => {
    const body = this.state.body;
    this.setState({ body: !body });
  };

  showDuplicateModal = () => {
    const { rule } = this.props;
    ModalManager.show({
      title: `Duplicate Rule`,
      body: (
        <CommonRuleModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleDuplicateRule}
          rule={rule}
          mode={"duplicate"}
        />
      ),
      footer: " ",
    });
  };

  showEditModal = () => {
    const { rule } = this.props;
    ModalManager.show({
      title: `Edit Rule`,
      body: (
        <CommonRuleModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleEditRule}
          rule={rule}
          mode={"edit"}
        />
      ),
      footer: " ",
    });
  };

  confirmRemoveRule = () => {
    ModalManager.show({
      title: `Delete Confirmation`,
      type: "default",
      body: `Are you sure you want to delete this rule?`,
      footer: (
        <div>
          <Button variant="link" onClick={() => ModalManager.dismiss()}>
            Cancel
          </Button>
          <Button variant="blue" onClick={() => this.handleRemoveRule()}>
            Proceed
          </Button>
        </div>
      ),
    });
  };

  handleCancelModalManager = () => {
    ModalManager.dismiss();
  };

  handleEditRule = (newRuleValue) => {
    const { index, actions, rule } = this.props;
    newRuleValue._id = rule._id;
    newRuleValue.numOrder = index;
    actions.editRule(index, newRuleValue);
    ModalManager.dismiss();
  };

  handleDuplicateRule = (value) => {
    const { actions, rule } = this.props;
    const copiedRule = JSON.parse(JSON.stringify(rule));
    const newRule = {
      ...value,
      conditions: copiedRule.conditions,
      actions: copiedRule.actions,
    };
    actions.addRule(newRule);
    ModalManager.dismiss();
  };

  handleRemoveRule = () => {
    const { index, actions } = this.props;
    actions.removeRule(index);
    ModalManager.dismiss();
  };

  handleMoveUp = (e) => {
    e.stopPropagation();
    const { index, actions } = this.props;
    if (index <= 0) return;
    actions.moveRule(index, index - 1);
  };

  handleMoveDown = (e) => {
    e.stopPropagation();
    const { index, lastIndex, actions } = this.props;
    if (index >= lastIndex - 1) return;
    actions.moveRule(index, index + 1);
  };

  handleClickAddCondition = () => {
    ModalManager.show({
      title: `Add New Condition`,
      body: (
        <ConditionModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleAddCondition}
        />
      ),
      footer: " ",
    });
  };

  handleAddCondition = (condition) => {
    const { index, actions } = this.props;
    condition.leaf = [];
    actions.addCondition(index, condition);
    ModalManager.dismiss();
  };

  handleAddAction = (action) => {
    const { index, actions } = this.props;
    let isValid = true;
    for (const i in action) {
      if (!action[i]) {
        isValid = false;
        break;
      }
    }

    if (isValid) {
      actions.addAction(index, action);
      ModalManager.dismiss();
    } else {
      NotificationManager.showError("Input is not valid, please re-check");
    }
  };

  handleClickAddAction = () => {
    ModalManager.show({
      title: `Add New Action`,
      body: (
        <ActionModal
          onCancel={this.handleCancelModalManager}
          onSave={this.handleAddAction}
          existingValue={null}
        />
      ),
      footer: " ",
    });
  };

  componentDidUpdate(prevProps) {
    if (prevProps.show !== this.props.show) {
      this.setState({ body: this.props.show });
    }
  }

  shouldComponentUpdate(nextProps, nextState) {
    const { rule, show, isDragging, index, lastIndex } = this.props;
    const { body } = this.state;
    return (
      nextProps.rule !== rule ||
      nextProps.show !== show ||
      nextProps.isDragging !== isDragging ||
      nextProps.index !== index ||
      nextProps.lastIndex !== lastIndex ||
      nextState.body !== body
    );
  }

  render() {
    const { rule, isDragging, index, lastIndex } = this.props;
    const isFirst = index <= 0;
    const isLast = index >= lastIndex - 1;
    const actions = [
      {
        action: this.showDuplicateModal,
        label: "Duplicate",
        style: { width: "1%" },
        component: Button,
        props: { size: BUTTON_SIZE.SMALL, variant: BUTTON_VARIANT.LINK },
      },
      {
        action: this.showEditModal,
        label: "Edit",
        style: { width: "1%" },
        component: Button,
        props: { size: BUTTON_SIZE.SMALL, variant: BUTTON_VARIANT.LINK },
      },
      {
        action: this.confirmRemoveRule,
        label: "Delete",
        style: { width: "1%" },
        component: Button,
        props: { size: BUTTON_SIZE.SMALL, variant: BUTTON_VARIANT.LINK },
      },
    ];
    const condition = this.getRuleConditions();
    const action = this.getRuleActions();

    return (
      <div
        className={cx(style.rule, { [style.dragging]: isDragging })}
        ref={this.attachDropTarget}
      >
        <div className={cx(style.ruleBox, { expand: this.state.body })}>
          <div
            className={cx(style.head, { enabled: rule.enabled })}
            onClick={this.handleShowHideBody}
          >
            <div className={style.orderButton}>
              <a
                className={cx({ disabled: isFirst })}
                onClick={isFirst ? undefined : this.handleMoveUp}
                title="Move up"
              >
                <Icon icon="chevron-up" />
              </a>
              <a
                className={cx({ disabled: isLast })}
                onClick={isLast ? undefined : this.handleMoveDown}
                title="Move down"
              >
                <Icon icon="chevron-down" />
              </a>
            </div>
            <div className={style.menu}>
              <ToggleTooltip theme={ToggleTooltip.THEME.WHITE}>
                {this.generateItemAction(actions)}
              </ToggleTooltip>
            </div>
            <div className={style.header} ref={this.attachDragPreview}>
              <p className={style.name}>{rule.name}</p>
              <p className={style.priority}>
                {"Priority :"} {rule.priority}
              </p>
            </div>
          </div>
          <div className={style.body}>
            {rule.description && (
              <div className={style.description}>{rule.description}</div>
            )}
            <div className={style.contentTitle}>
              <span className={style.conditionTitle}>
                {"If conditions below meet"}
              </span>
            </div>
            <div className={style.content}>
              {condition}
              <div>
                {rule && rule.conditions && rule.conditions.length === 0 ? (
                  <Button
                    variant={BUTTON_VARIANT.LINK}
                    size={BUTTON_SIZE.SMALL}
                    onClick={this.handleClickAddCondition}
                  >
                    {"Add new condition"}
                  </Button>
                ) : null}
              </div>
            </div>
            <div className={style.contentTitle}>
              <span className={style.conditionTitle}>
                {"Do the following actions"}
              </span>
            </div>
            <div className={style.content}>
              {action}
              <Button
                variant={BUTTON_VARIANT.LINK}
                size={BUTTON_SIZE.SMALL}
                onClick={this.handleClickAddAction}
              >
                {"Add new action"}
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

CommonRuleComponent.propTypes = {
  index: PropTypes.number.isRequired,
  rule: PropTypes.object,
  lastIndex: PropTypes.number.isRequired,
  show: PropTypes.bool.isRequired,
  actions: PropTypes.object.isRequired,
  isDragging: PropTypes.bool,
};

const mapStateToProps = (state, ownProps) => ({
  rule: commonRulesSelector.getRule(state, ownProps.index),
});

const mapDispatchToProps = (dispatch, ownProps) => ({
  actions: bindActionCreators(commonRulesMapDisToProps, dispatch),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, mapDispatchToProps)
)(CommonRuleComponent);
